_apiBase: '/api/plugins/com.promptkit.project',

_isEN: function() { try { return (localStorage.getItem('promptkit_lang')||'zh-CN')==='en'; } catch(e) { return false; } },
_L: function(zh, en) { return this._isEN() ? (en||zh) : zh; },

open: function() {
  var vp = document.getElementById('viewProjectMgmt');
  if (!vp) { vp = document.createElement('div'); vp.id = 'viewProjectMgmt'; vp.className = 'view-panel active-view'; vp.style.display = 'flex'; var mc = document.getElementById('mainContent'); if (mc) mc.appendChild(vp); }
  document.querySelectorAll('#mainContent > .view-panel').forEach(function(p){p.style.display='none';}); vp.style.display = 'flex'; this._init();
},
